#include "study_native_kernels.cuh"
#include <vector>
#include <tuple>
#include <string>
#include <filesystem>
#include <fstream>
template<class T>std::vector<T>readvec(std::filesystem::path p){std::ifstream in(p,std::ios::binary);std::vector<char>b((std::istreambuf_iterator<char>(in)),{});std::vector<T>a(b.size()/sizeof(T));memcpy(a.data(),b.data(),b.size());return a;}
template<class T>struct StudyCase{int type,h,nt,n;float fixed_scale;int32_t fixed_azp;std::vector<T>host;T*input;int8_t*out[4];float*sc[4];int32_t*zp[4];std::vector<double>expected;std::vector<float>blank_scale;std::vector<int32_t>blank_zp;StudyCase(const std::vector<uint32_t>&words,size_t&pos){type=words[pos++];h=words[pos++];nt=words[pos++];uint32_t sb=words[pos++];memcpy(&fixed_scale,&sb,4);fixed_azp=words[pos++];n=h*nt;host.resize(n);for(int i=0;i<n;i++){uint32_t b=words[pos++];if constexpr(sizeof(T)==2){uint16_t s=b;memcpy(host.data()+i,&s,2);}else memcpy(host.data()+i,&b,4);}cudaMalloc(&input,n*sizeof(T));cudaMemcpy(input,host.data(),n*sizeof(T),cudaMemcpyHostToDevice);blank_scale.assign(nt+17,-12345.f);blank_zp.assign(nt+17,-123456);for(int mode=0;mode<4;mode++){cudaMalloc(&out[mode],n+17);cudaMalloc(&sc[mode],(nt+17)*4);cudaMalloc(&zp[mode],(nt+17)*4);std::vector<int8_t>o(n+17,int8_t(-99));auto s=blank_scale;auto z=blank_zp;if(mode==0)static_scaled_int8_quant_reference(host.data(),o.data(),fixed_scale,nt,h);else if(mode==1)static_scaled_int8_azp_quant_reference(host.data(),o.data(),fixed_scale,fixed_azp,nt,h);else if(mode==2)dynamic_scaled_int8_quant_reference(host.data(),o.data(),s.data(),nt,h);else dynamic_scaled_int8_azp_quant_reference(host.data(),o.data(),s.data(),z.data(),nt,h);for(auto v:o)expected.push_back(v);for(auto v:s)expected.push_back(v);for(auto v:z)expected.push_back(v);reset(mode);}}void reset(int mode){cudaMemset(out[mode],uint8_t(-99),n+17);cudaMemcpy(sc[mode],blank_scale.data(),(nt+17)*4,cudaMemcpyHostToDevice);cudaMemcpy(zp[mode],blank_zp.data(),(nt+17)*4,cudaMemcpyHostToDevice);}void execute(int mode){if(mode<2)static_scaled_int8_quant(out[mode],input,h,nt,fixed_scale,mode==0?0:fixed_azp);else dynamic_scaled_int8_quant(out[mode],input,h,nt,sc[mode],mode==2?nullptr:zp[mode]);}void warm(){for(int mode=0;mode<4;mode++)execute(mode);}void trial(int rep,std::vector<double>&times,std::vector<double>&got){for(int mode=0;mode<4;mode++){reset(mode);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)execute(mode);cudaDeviceSynchronize();times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/rep);std::vector<int8_t>o(n+17);std::vector<float>s(nt+17);std::vector<int32_t>z(nt+17);cudaMemcpy(o.data(),out[mode],o.size(),cudaMemcpyDeviceToHost);cudaMemcpy(s.data(),sc[mode],s.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(z.data(),zp[mode],z.size()*4,cudaMemcpyDeviceToHost);for(auto v:o)got.push_back(v);for(auto v:s)got.push_back(v);for(auto v:z)got.push_back(v);}}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;auto dir=std::filesystem::path(__FILE__).parent_path();auto words=readvec<uint32_t>(dir/"fixture_bits.bin");auto expected=readvec<double>(dir/"expected_full_outputs.bin");size_t pos=0;std::tuple<StudyCase<__half>,StudyCase<__half>,StudyCase<__nv_bfloat16>,StudyCase<__nv_bfloat16>,StudyCase<float>,StudyCase<float>>cases{StudyCase<__half>(words,pos),StudyCase<__half>(words,pos),StudyCase<__nv_bfloat16>(words,pos),StudyCase<__nv_bfloat16>(words,pos),StudyCase<float>(words,pos),StudyCase<float>(words,pos)};std::vector<double>cpu;std::apply([&](auto&...c){(cpu.insert(cpu.end(),c.expected.begin(),c.expected.end()),...);},cases);printf("CPU_REFERENCE_ORACLE_MATCH %s values=%zu prefix=%zu\n",cpu==expected?"true":"false",cpu.size(),pos);if(cpu!=expected||pos!=words.size()){for(size_t i=0;i<std::min(cpu.size(),expected.size());i++)if(cpu[i]!=expected[i]){printf("FIRST_CPU_DIFF %zu %.17g %.17g\n",i,cpu[i],expected[i]);break;}return 2;}std::apply([](auto&...c){(c.warm(),...);},cases);cudaDeviceSynchronize();for(int t=1;t<=5;t++){std::vector<double>got,times;std::apply([&](auto&...c){(c.trial(rep,times,got),...);},cases);bool ok=cudaGetLastError()==cudaSuccess&&got==expected;double ma=0,total=0;for(size_t i=0;i<got.size();i++)ma=std::max(ma,fabs(got[i]-expected[i]));for(auto v:times)total+=v;std::vector<double>artifact;for(auto w:words)artifact.push_back(w);artifact.insert(artifact.end(),got.begin(),got.end());std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(t)+".bin";FILE*f=fopen(file.c_str(),"wb");fwrite(artifact.data(),8,artifact.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"timing_region\":\"sum24_FP16_BF16_FP32_static_dynamic_quantization_kernels_only\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[",t,total,ok?"true":"false",got.size(),ma,rep);for(size_t i=0;i<times.size();i++)printf(i?",%.17g":"%.17g",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",file.c_str(),artifact.size());}}
